const revokeDeviceToken = `-- name: RevokeDeviceToken :execrows
UPDATE device_tokens
SET revoked_at = now(),
    updated_at = now()
WHERE token_hash = $1
  AND revoked_at IS NULL
`

func (q *Queries) RevokeDeviceToken(ctx context.Context, tokenHash string) (int64, error) {
	result, err := q.db.Exec(ctx, revokeDeviceToken, tokenHash)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

