const upsertDeviceToken = `-- name: UpsertDeviceToken :one
INSERT INTO device_tokens (
    id,
    user_id,
    token_hash,
    provider,
    platform,
    last_used_at,
    revoked_at
) VALUES (
    $1, $2, $3, $4, $5, $6, $7
)
ON CONFLICT (token_hash)
DO UPDATE SET
    user_id = EXCLUDED.user_id,
    provider = EXCLUDED.provider,
    platform = EXCLUDED.platform,
    last_used_at = COALESCE(EXCLUDED.last_used_at, now()),
    revoked_at = NULL,
    updated_at = now()
RETURNING id, user_id, token_hash, provider, platform, last_used_at, revoked_at, created_at, updated_at
`

type UpsertDeviceTokenParams struct {
	ID         uuid.UUID   `json:"id"`
	UserID     uuid.UUID   `json:"user_id"`
	TokenHash  string      `json:"token_hash"`
	Provider   string      `json:"provider"`
	Platform   pgtype.Text `json:"platform"`
	LastUsedAt *time.Time  `json:"last_used_at"`
	RevokedAt  *time.Time  `json:"revoked_at"`
}

func (q *Queries) UpsertDeviceToken(ctx context.Context, arg UpsertDeviceTokenParams) (DeviceToken, error) {
	row := q.db.QueryRow(ctx, upsertDeviceToken,
		arg.ID,
		arg.UserID,
		arg.TokenHash,
		arg.Provider,
		arg.Platform,
		arg.LastUsedAt,
		arg.RevokedAt,
	)
	var i DeviceToken
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.TokenHash,
		&i.Provider,
		&i.Platform,
		&i.LastUsedAt,
		&i.RevokedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

